const students = [
  { name: "小雨", city: "上海", age: 18 },
  { name: "小林", city: "北京", age: 19 },
  { name: "小周", city: "北京", age: 18 },
  { name: "小陈", city: "深圳", age: 20 }
];

// WHERE：先筛出 city 是北京的行。
const filteredRows = students.filter((student) => student.city === "北京");

// SELECT：再从留下的行中取出 name 和 age 两列。
const selectedColumns = filteredRows.map((student) => ({ name: student.name, age: student.age }));

console.log("查询结果:", selectedColumns);
